class KeyCard {
    private int code;
    public KeyCard(int code) { this.code = code; }
}

public class DoubleEqualsDemo {
    public static void main(String[] args) {
        // Two separate new allocations in heap
        KeyCard card1 = new KeyCard(9901);
        KeyCard card2 = new KeyCard(9901);

        // An alias pointing to card1
        KeyCard card3 = card1;

        System.out.println("card1 == card2: " + (card1 == card2)); // false! Different addresses
        System.out.println("card1 == card3: " + (card1 == card3)); // true! Same address alias
    }
}

