public class IntegerCacheDemo {
    public static void main(String[] args) {
        // Within byte range (-128 to 127): Integer.valueOf caches instances
        Integer x1 = 100;
        Integer x2 = 100;
        System.out.println("100 == 100 (Cached):   " + (x1 == x2)); // true

        // Outside byte range: Integer.valueOf allocates brand new objects
        Integer y1 = 200;
        Integer y2 = 200;
        System.out.println("200 == 200 (Uncached): " + (y1 == y2)); // FALSE!

        // Proper logical equality check:
        System.out.println("200 .equals 200:        " + y1.equals(y2)); // true
    }
}

