class SessionToken {
    private String tokenStr;
    public SessionToken(String tokenStr) {
        this.tokenStr = tokenStr;
    }
}

class IdentityInspector {
    public static void inspectRelationship(SessionToken a, SessionToken b) {
        if (a == b) {
            System.out.println("Same Reference: Exact identical heap instance");
        } else {
            System.out.println("Distinct References: Separate heap allocations");
        }
    }
}

public class IdentityApp {
    public static void main(String[] args) {
        SessionToken t1 = new SessionToken("AUTH-1");
        SessionToken t2 = new SessionToken("AUTH-1");
        SessionToken t3 = t1;

        IdentityInspector.inspectRelationship(t1, t2);
        IdentityInspector.inspectRelationship(t1, t3);
    }
}

enum OrderStatus {
    PENDING, PROCESSING, SHIPPED, DELIVERED
}

class OrderTracker {
    private OrderStatus status;
    public OrderTracker(OrderStatus status) {
        this.status = status;
    }
    public boolean isShipped() {
        return this.status == OrderStatus.SHIPPED;
    }
    public boolean isDelivered() {
        return this.status == OrderStatus.DELIVERED;
    }
}

public class EnumApp {
    public static void main(String[] args) {
        OrderTracker o1 = new OrderTracker(OrderStatus.SHIPPED);
        System.out.println("Shipped: " + o1.isShipped());

        OrderTracker o2 = new OrderTracker(null);
        System.out.println("Shipped (null status): " + o2.isShipped());
    }
}

