class CacheTester {
    public static void testRange(int value) {
        Integer a = value;
        Integer b = value;
        if (a == b) {
            System.out.println("Value " + value + " -> CACHED (Same Address)");
        } else {
            System.out.println("Value " + value + " -> UNCACHED (Distinct Addresses)");
        }
    }
}

public class CacheTesterApp {
    public static void main(String[] args) {
        CacheTester.testRange(127);
        CacheTester.testRange(128);
        CacheTester.testRange(-128);
        CacheTester.testRange(-129);
    }
}
